//! `rust`: a unified song as Rust source for a compo build (shrink-unified-synth 4.4).
//!
//! The song is loaded on the host with the real player (every module, the given DLS bank), so every check the player
//! runs at load (song layout, instrument and effect chunks, modules, automation targets, receive cycles) runs once,
//! here. The generated file then holds the song's validated sections as byte arrays, byte for byte the blob's, so the
//! player's own iterators decode them unchanged, and a compile-time assert that the build has every module the song
//! needs. A build with `unisynth/us-trusted` can then leave the load-time validation out.

use crate::features::features;
use crate::ConvError;
use std::fmt::Write;
use synth_core::mix::{Env, Player, Song, DEFAULT_SUB};
use synth_core::pool::Pool;
use unisynth::device::UDevice;
use unisynth::rng::Xorshift;

/// A validated song, ready to be written as Rust.
#[derive(Clone, Debug, PartialEq)]
pub struct Baked {
    pub tempo: i32,
    pub rate: i32,
    /// `length.to_bits()`: written as `f64::from_bits` so the frame count is exact.
    pub length_bits: u64,
    /// Devices, lanes, tracks: `(count, bytes)` as `Song::sections` gives them.
    pub sections: [(usize, Vec<u8>); 3],
    /// The module ids the song needs, in module order (`synth-convert features` names them).
    pub modules: Vec<u8>,
}

/// Loads `blob` with the unified player and returns its sections and modules; any load error refuses the song.
pub fn bake(blob: &[u8], bank: Option<&[u8]>) -> Result<Baked, ConvError> {
    let song = Song::parse(blob).map_err(|e| ConvError::Input(format!("not a song: {e:?}")))?;
    let names = features(blob)?;
    let env = Env::for_song(&song, bank);
    let refuse = |e| ConvError::Input(format!("the player refuses the song: {e:?}"));
    let need = Player::<UDevice, Xorshift>::required_pool(&song, &env, DEFAULT_SUB).map_err(refuse)?;
    let mut mem = vec![0u8; need];
    let mut pool = Pool::new(&mut mem);
    Player::<UDevice, Xorshift>::new(song, &env, &mut pool, Xorshift::new(1), DEFAULT_SUB).map_err(refuse)?;
    let id = |f: &str| unisynth::module::ALL.iter().copied().find(|&m| unisynth::module::feature(m) == f);
    let modules = names.iter().map(|f| id(f).ok_or_else(|| ConvError::Input(format!("no module for feature {f}")))).collect::<Result<_, _>>()?;
    Ok(Baked {
        tempo: song.tempo,
        rate: song.rate,
        length_bits: song.length.to_bits(),
        sections: song.sections().map(|(n, b)| (n, b.to_vec())),
        modules,
    })
}

/// The Rust source of `blob` (`name` goes into the header): `pub static SONG: Song<'static>` plus the module assert.
pub fn generate(blob: &[u8], bank: Option<&[u8]>, name: &str) -> Result<String, ConvError> {
    let b = bake(blob, bank)?;
    let ids = b.modules.iter().map(|id| id.to_string()).collect::<Vec<_>>().join(", ");
    let feats = b.modules.iter().map(|&id| unisynth::module::feature(id)).collect::<Vec<_>>().join(",");
    let mut o = String::new();
    // writing to a String cannot fail
    let _ = writeln!(o, "// Generated by `synth-convert rust` from {name}. Do not edit: regenerate from the song.");
    let _ = writeln!(o, "// unisynth features: {feats}");
    let _ = writeln!(o, "const _: () = assert!(unisynth::module::compiled_all(&[{ids}]), \"the build lacks a unisynth module this song needs\");");
    for (i, (_, s)) in b.sections.iter().enumerate() {
        let _ = writeln!(o, "static S{i}: [u8; {}] = {:?};", s.len(), s);
    }
    let [(d, _), (l, _), (t, _)] = &b.sections;
    let _ = writeln!(
        o,
        "pub static SONG: synth_core::mix::Song<'static> = synth_core::mix::Song::from_sections({}, {}, f64::from_bits({:#x}), [({d}, &S0), ({l}, &S1), ({t}, &S2)]);",
        b.tempo, b.rate, b.length_bits
    );
    Ok(o)
}
